        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>AFFLICTIONS</strong> common to all (Job 5:7; 14:1; Psalm 34:19); are for the good of men (James 1:2, 3, 12; 2 Corinthians 12:7) and the glory of God (2 Corinthians 12:7-10; 1 Peter 4:14), and are to be borne with patience by the Lord’s people (Psalm 94:12; Proverbs 3:12). They are all directed by God (Lamentations 3:33), and will result in the everlasting good of his people (2 Corinthians 4:16-18) in Christ Jesus (Romans 8:35-39).",
