        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BROOK</strong> a torrent. (1.) Applied to small streams, as the Arnon, Jabbok, etc. Isaiah (15:7) speaks of the “book of the willows,” probably the Wady-el-Asha. (2.) It is also applied to winter torrents (Job 6:15; Numbers 34:5; Joshua 15:4, 47), and to the torrent-bed or wady as well as to the torrent itself (Numbers 13:23; 1 Kings 17:3). (3.) In Isaiah 19:7 the river Nile is meant, as rendered in the Revised Version.",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
