        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>GHOST</strong> an old Saxon word equivalent to soul or spirit. It is the translation of the Hebrew nephesh and the Greek pneuma, both meaning “breath,” “life,” “spirit,” the “living principle” (Job 11:20; Jeremiah 15:9; Matthew 27:50; John 19:30). The expression “to give up the ghost” means to die (Lamentations 1:19; Genesis 25:17; 35:29; 49:33; Job 3:11). (See HOLY GHOST.)",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
