        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>HISS</strong> to express contempt (Job 27:23). The destruction of the temple is thus spoken of (1 Kings 9:8). Zechariah (10:8) speaks of the Lord gathering the house of Judah as it were with a hiss: “I will hiss for them.” This expression may be “derived from the noise made to attract bees in hiving, or from the sound naturally made to attract a person’s attention.”",
